void report(const char *name, size_t count, long total) {
  char tag[5];
  memcpy(tag, name, 4);
  tag[4] = '\0';
  printf("%s: %zu items, %ld bytes\n", tag, count, total);
}

void report(const char *name, size_t count, unsigned long total) {
  printf("%s: %zu items, 0x%lx bytes\n", name, count, total);
}
